  // weight is %arg0, input is %arg1
  // weight shape: 7x7, input shape: 6x7
  // We need to transpose weight to 7x7 (which is same shape), but in general, for matmul, 
  // the operation is: %matmul = dot_general(%arg1, %arg0) with appropriate dimension numbers
  // Since weight is 7x7, and input is 6x7, to do input x weight.T, we do dot_general with contraction over dim=1 of input and dim=0 of weight
  // But in StableHLO, dot_general's dimension numbers specify batching and contracting dims.
  // Here, no batching dims, contracting dims: input dim 1, weight dim 0
  // So, input shape: [6,7], weight shape: [7,7], result shape: [6,7]
  %matmul = "stablehlo.dot_general"(%arg1, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

