// StableHLO program implementing the forward pass of the described PyTorch module
// Signature: func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<6x6x3x3xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x6x7x7xf32>) -> tensor<6x6x5x5xf32>

func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<6x6x3x3xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x6x7x7xf32>) -> tensor<6x6x5x5xf32> {
  // Step 1: Convolution
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

  // Step 2: Multiply convolution output by multiplier (broadcasted)
  // %arg0: tensor<6x1x1xf32> (multiplier)
  // %conv: tensor<6x6x5x5xf32>
  // Broadcast %arg0 to shape of %conv
  %multiplier_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = array<i64: 1, 2, 3>
  } : (tensor<6x1x1xf32>) -> tensor<6x6x1x1xf32>

  // Broadcast to match shape of conv output
  %multiplier_bcast2 = "stablehlo.broadcast_in_dim"(%multiplier_bcast) {
    broadcast_dimensions = array<i64: 1, 2, 3>
  } : (tensor<6x6x1x1xf32>) -> tensor<6x6x5x5xf32>

  // Element-wise multiply
  %mul = "stablehlo.multiply"(%conv, %multiplier_bcast2) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // Step 3: Apply LeakyReLU
  // LeakyReLU with negative slope = 0.01
  // Implement as max(%mul, 0) + 0.01 * min(%mul, 0)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %alpha = "stablehlo.constant"() {value = dense<0.01> : tensor<f32>} : () -> tensor<f32>

  // max(%mul, 0)
  %leaky_part1 = "stablehlo.maximum"(%mul, %zero) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>
  // min(%mul, 0) = -max(-%mul, 0)
  %neg_mul = "stablehlo.negate"(%mul) : (tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>
  %min_part = "stablehlo.maximum"(%neg_mul, %zero) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>
  %min_part_scaled = "stablehlo.multiply"(%min_part, %alpha) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>
  %leaky_relu = "stablehlo.subtract"(%leaky_part1, %min_part_scaled) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // Step 4: Apply GELU
  // GELU approximation: 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
  // Constants
  %one_half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %sqrt_2_over_pi = "stablehlo.constant"() {value = dense<0.7978845608> : tensor<f32>} : () -> tensor<f32>
  %coeff = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>} : () -> tensor<f32>

  // x^3
  %x_cubed = "stablehlo.multiply"(%leaky_relu, %leaky_relu) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>
  %x_cubed2 = "stablehlo.multiply"(%x_cubed, %leaky_relu) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // 0.044715 * x^3
  %term1 = "stablehlo.multiply"(%coeff, %x_cubed2) : (tensor<f32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // x + 0.044715 * x^3
  %x_plus = "stablehlo.add"(%leaky_relu, %term1) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // √(2/π) * (x + 0.044715 * x^3)
  %inner = "stablehlo.multiply"(%sqrt_2_over_pi, %x_plus) : (tensor<f32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // tanh
  %tanh = "chlo.tanh"(%inner) : (tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // 1 + tanh(...)
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %tanh_plus_one = "stablehlo.add"(%one, %tanh) : (tensor<f32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // Final GELU: 0.5 * x * (1 + tanh(...))
  %gelu = "stablehlo.multiply"(%leaky_relu, %tanh_plus_one) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>
  %gelu_final = "stablehlo.multiply"(%gelu, %one_half) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>

  // Return the result
  return %gelu_final : tensor<6x6x5x5xf32>
}

func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<6x6x3x3xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x6x7x7xf32>) -> tensor<6x6x5x5xf32> {
    // Step 1: Convolution
    %conv_result = "stablehlo.convolution"(%arg3, %arg1) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

    // Step 2: Broadcast %arg0 (multiplier) to shape of convolution output
    // %arg0 shape: 6x1x1xf32, need to broadcast to 6x6x5x5xf32
    %bcast_multiplier = "stablehlo.broadcast_in_dim"(%arg0) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<6x1x1xf32>) -> tensor<6x6x5x5xf32>
    // The broadcast_dimensions map each input dimension to the output dimension
    // Since input shape is 6x1x1xf32, output shape is 6x6x5x5xf32
    // We need to broadcast along the second, third, and fourth dims
    // So, broadcast_dimensions = [0, 1, 2, 3], with input dims mapped to output dims
    // But since input dims are 6,1,1, and output is 6,6,5,5, we need to specify broadcast_dimensions accordingly
    // Actually, the input dims: 0:6, 1:1, 2:1, 3:? (but input only has 4 dims)
    // The input shape: 6x1x1xf32, output shape: 6x6x5x5xf32
    // To broadcast, we need to specify broadcast_dimensions as [0, 1, 2, 3], mapping input dims to output dims
    // But input dims: 0,1,2,3; output dims: 0,1,2,3
    // The input dims 1 and 2 are 1, so they are broadcasted along output dims 1 and 2
    // So, broadcast_dimensions = [0, 1, 2, 3]
    // But the input shape is 4D, so broadcast_dimensions should be [0, 1, 2, 3]
    // The output shape is 6x6x5x5, so the broadcast dims are [0, 1, 2, 3]
    // But the input shape is 4D, so the broadcast_dimensions should be [0, 1, 2, 3]
    // Wait, the input shape is 6x1x1xf32, so dims: 0,1,2,3
