// StableHLO program implementing the described model forward pass
module {
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Constants for parameters
    %c_one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %c_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Parameters: bmm.weight and bmm.bias
    // %arg0: tensor<7x7xf32> (bmm.weight)
    // %arg1: tensor<7xf32> (bmm.bias)
    // Inputs: %arg2, %arg3: tensor<6x7xf32>

    // Step 1: bmm = linear transformation
    // Perform dot_general: %bmm = "stablehlo.dot_general"(%arg2, %arg0)
    // with lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]
    %dot_dim_nums = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    %bmm = "stablehlo.dot_general"(%arg2, %arg0) {dot_dimension_numbers = %dot_dim_nums} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: InstanceNorm2d on %bmm
    // Since InstanceNorm2d is not directly available, emulate with mean and variance
    // Compute mean over spatial dims (which are 1,1), but here, shape is 6x7, so axes are 0 and 1
    // For simplicity, approximate normalization: subtract mean, divide by std
    // Compute mean over axes [0,1]
    %axes = "stablehlo.constant"() {value = dense<[0, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
    %bmm_mean = "stablehlo.reduce"(%bmm, %c_zero) {
      dimensions = %axes
    } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    // For variance, compute squared difference
    %diff = "stablehlo.subtract"(%bmm, "stablehlo.broadcast_in_dim"(%bmm_mean) {broadcast_dimensions = 0:2}) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %var = "stablehlo.reduce"(%diff_sq, %c_zero) {
      dimensions = %axes
    } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Compute std = sqrt(var + epsilon)
