    %var_plus_eps = "stablehlo.add"(%var, %epsilon) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    %std = "stablehlo.sqrt"(%var_plus_eps) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Normalize: (x - mean) / std
    %bmm_broadcast_mean = "stablehlo.broadcast_in_dim"(%bmm_mean) {broadcast_dimensions = 0:2} : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %bmm_centered = "stablehlo.subtract"(%bmm, %bmm_broadcast_mean) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %bmm_norm = "stablehlo.divide"(%bmm_centered, %std) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Add %arg3 (tensor<6x7xf32>) to normalized output
    %add1 = "stablehlo.add"(%bmm_norm, %arg3) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: Multiply the result by %arg3
    %mul1 = "stablehlo.multiply"(%add1, %arg3) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 5: Add residual: previous result + normalized output
    %residual = "stablehlo.add"(%mul1, %bmm_norm) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 6: Final output is residual (as per the model's forward)
    // Return residual
    return %residual : tensor<6x7xf32>
  }
