    %matmul = "stablehlo.dot_general"(%arg2, %arg0) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: %linear = matmul + bias
    %linear = "stablehlo.add"(%matmul, %arg1) : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>
    // Note: bias shape is 7, need to broadcast to 6x7
    // Broadcast bias to shape 6x7
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // Actually, to match the shape, broadcast bias to 6x7
    // But since bias is 7, broadcast along dimension 0
    // So, broadcast bias to shape 6x7 with broadcast_dimensions [1]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
