    %linear = "stablehlo.add"(%matmul, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Step 2: Apply Mish activation twice
    // Mish: x * tanh(softplus(x))
    // softplus(x) = log(1 + exp(x))
    // Compute exp(x)
