    // Add 1 to exp(x)
    %exp_plus_one = "stablehlo.add"(%exp_x, %one) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute softplus(x) = log(exp(x) + 1)
    %softplus = "stablehlo.log"(%exp_plus_one) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute tanh(softplus(x))
    %tanh_sp = "stablehlo.tanh"(%softplus) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute Mish: x * tanh(softplus(x))
    %mish1 = "stablehlo.multiply"(%linear, %tanh_sp) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Apply Mish again
    // exp of previous Mish output
    %exp_mish1 = "stablehlo.exponential"(%mish1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // exp_mish1 + 1
    %exp_mish1_plus_one = "stablehlo.add"(%exp_mish1, %one) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // log of above
    %log_mish1 = "stablehlo.log"(%exp_mish1_plus_one) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // tanh of log_mish1
    %tanh_log_mish1 = "stablehlo.tanh"(%log_mish1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Final Mish: mish2 = mish1 * tanh(log(mish1))
    %mish2 = "stablehlo.multiply"(%mish1, %tanh_log_mish1) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Output is mish2
    return %mish2 : tensor<6x7xf32>
  }
}

