module {
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Step 1: GEMM (matrix multiplication)
    %gemm_result = "stablehlo.dot_general"(%arg2, %arg0) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: Add bias
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %add_bias = "stablehlo.add"(%gemm_result, %bias_broadcasted) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Swish activation: x * sigmoid(x)
    // Compute sigmoid(x) = 1 / (1 + exp(-x))
    %neg_x = "stablehlo.negate"(%add_bias) : tensor<6x7xf32>
    %exp_neg_x = "stablehlo.exponential"(%neg_x) : tensor<6x7xf32>
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %denominator = "stablehlo.add"(%one_const, %exp_neg_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid_x = "stablehlo.divide"(%one_const, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %swish = "stablehlo.multiply"(%add_bias, %sigmoid_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: Divide by 2.0
    %two_const = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
    %divided = "stablehlo.divide"(%swish, %two_const) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>

    // Step 5: Clamp between -1 and 1
    // min with 1
    %one_const2 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %clamp_max = "stablehlo.maximum"(%divided, %neg_one_const) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
    // Actually, to clamp between -1 and 1, do min with 1 and max with -1
    %neg_one_const = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
    %clamped_max = "stablehlo.minimum"(%divided, %one_const2) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
    %clamped = "stablehlo.maximum"(%clamped_max, %neg_one_const) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>

    // Step 6: Tanh activation
    %tanh_x = "stablehlo.tanh"(%clamped) : tensor<6x7xf32>

    // Step 7: Clamp again between -1 and 1
    %clamped_max2 = "stablehlo.minimum"(%tanh_x, %one_const2) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
    %final_output = "stablehlo.maximum"(%clamped_max2, %neg_one_const) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>

    return %final_output : tensor<6x7xf32>
  }
}

