      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<16x6x6x6x6xf32>, tensor<7x6x5x5x5xf32>) -> tensor<16x7x6x6x6xf32>

    // Step 3: Add bias
