    // bias shape: [7], output shape: [16,7,6,6,6]
    // broadcast bias over batch and spatial dims
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<16x7x6x6x6xf32>
    // But to broadcast bias over batch and spatial dims, need to specify broadcast dims
    // Actually, broadcast_in_dim with bias shape [7], target shape [16,7,6,6,6]
    // broadcast_dimensions: [1], since bias dims: [0], target dims: [0,1,2,3,4]
    // But in StableHLO, broadcasting scalar to tensor is straightforward; for vector to tensor, specify dims
    // So, broadcast bias over dims 1,2,3,4
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<16x7x6x6x6xf32>

    // Add bias
