    %epsilon = "stablehlo.constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %var_eps = "stablehlo.add"(%var, %epsilon) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // Compute stddev = sqrt(var_eps)
    %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<6x7xf32>) -> tensor<6x7xf32>

    // Normalize: (x - mean) / stddev
    %x_centered = "stablehlo.subtract"(%scaled_x, "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = [0]} : (tensor<6x7xf32>) -> tensor<6x7xf32>) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %normalized = "stablehlo.divide"(%x_centered, %stddev) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: Add bias: %arg4 (bn.bias)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = [0]} : (tensor<7xf32>) -> tensor<6x7xf32>
    %bn_output = "stablehlo.add"(%normalized, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 5: Return the result
    "stablehlo.return"(%bn_output) : (tensor<6x7xf32>) -> ()
  }
}

// StableHLO program to produce a lower triangular matrix with the input tensor x
// where out[i, j] = x[i, j] if j <= i, else 0.0

func.func @main(%x: tensor<5x5xf32>) -> tensor<5x5xf32> {
  %dim0 = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<5x1xi32>
  %dim1 = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<5x1xi32>

