  %dim0_reshaped = "stablehlo.reshape"(%dim0) {shape = dense<[5, 1]> : tensor<2xi64>} : (tensor<5x1xi32>) -> tensor<5x1xi32>
  %dim1_reshaped = "stablehlo.reshape"(%dim1) {shape = dense<[1, 5]> : tensor<2xi64>} : (tensor<5x1xi32>) -> tensor<1x5xi32>

  // Broadcast to 2D shape
  %i_indices = "stablehlo.broadcast_in_dim"(%dim0_reshaped) {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : (tensor<5x1xi32>) -> tensor<5x5xi32>
  %j_indices = "stablehlo.broadcast_in_dim"(%dim1_reshaped) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<1x5xi32>) -> tensor<5x5xi32>

  // Convert to float for comparison
  %i_indices_f32 = "stablehlo.convert"(%i_indices) {to_element_type = #stablehlo<"f32">} : (tensor<5x5xi32>) -> tensor<5x5xf32>
  %j_indices_f32 = "stablehlo.convert"(%j_indices) {to_element_type = #stablehlo<"f32">} : (tensor<5x5xi32>) -> tensor<5x5xf32>

  // Compare j_indices <= i_indices
  %cmp = "stablehlo.compare"(%j_indices_f32, %i_indices_f32) {
    comparison_direction = #stablehlo<"LE">,
    compare_type = #stablehlo<"FLOAT">
  } : (tensor<5x5xf32>, tensor<5x5xf32>) -> tensor<5x5xi1>

  // Constant zero tensor
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Select between x and zero based on comparison
  %result = "stablehlo.select"(%cmp, %x, %zero) : (tensor<5x5xi1>, tensor<5x5xf32>, tensor<5x5xf32>) -> tensor<5x5xf32>

  return %result : tensor<5x5xf32>
}

