// StableHLO program implementing the described model forward pass
module {
  func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
    // Step 1: GEMM (matrix multiplication)
    %gemm_result = "stablehlo.dot_general"(%arg1, %arg5) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 2: BatchNorm (using batch statistics)
    // Compute mean over batch dimension (dim 0)
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %sum_over_batch = "stablehlo.reduce"(%gemm_result, %zero) ({
      ^bb0(%a: tensor<16x16xf32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
    }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Compute mean: divide sum by 16
    %div_const = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
    %batch_mean = "stablehlo.divide"(%sum_over_batch, %div_const) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

    // Compute variance
    // Subtract mean from gemm result
    %broadcast_mean = "stablehlo.broadcast_in_dim"(%batch_mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %diff = "stablehlo.subtract"(%gemm_result, %broadcast_mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Square the difference
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Sum squared differences over batch
    %sum_sq = "stablehlo.reduce"(%diff_squared, %zero) ({
      ^bb0(%a: tensor<16x16xf32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
    }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Variance = sum_sq / 16
    %variance = "stablehlo.divide"(%sum_sq, %div_const) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

    // Normalize: (x - mean) / sqrt(variance + epsilon)
    %epsilon = "stablehlo.constant"() {value = dense<1.1920929e-7> : tensor<f32>} : () -> tensor<f32>
    %var_plus_eps = "stablehlo.add"(%variance, %epsilon) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    %inv_sqrt_var = "stablehlo.rsqrt"(%var_plus_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %norm_num = "stablehlo.subtract"(%gemm_result, %broadcast_mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %normalized = "stablehlo.multiply"(%norm_num, %inv_sqrt_var) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 3: Swish activation: x * sigmoid(x)
    // Compute sigmoid(x) = 1 / (1 + exp(-x))
    %neg_normalized = "stablehlo.negate"(%normalized) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %exp_neg = "stablehlo.exponential"(%neg_normalized) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %denominator = "stablehlo.add"(%one, %exp_neg) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid_x = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Broadcast sigmoid_x to shape of normalized
    %sigmoid_bcast = "stablehlo.broadcast_in_dim"(%sigmoid_x) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
    // Swish: x * sigmoid(x)
    %swish1 = "stablehlo.multiply"(%normalized, %sigmoid_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 4: Multiply by parameter (arg0)
    // arg0 shape: (16,)
    %arg0_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %x1 = "stablehlo.multiply"(%swish1, %arg0_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 5: Swish again: x * sigmoid(x)
    %neg_x1 = "stablehlo.negate"(%x1) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %exp_neg_x1 = "stablehlo.exponential"(%neg_x1) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %denominator2 = "stablehlo.add"(%one, %exp_neg_x1) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid_x1 = "stablehlo.divide"(%one, %denominator2) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid_x1_bcast = "stablehlo.broadcast_in_dim"(%sigmoid_x1) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
    %output = "stablehlo.multiply"(%x1, %sigmoid_x1_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    return %output : tensor<16x16xf32>
  }
}

