    %diff = "stablehlo.subtract"(%gemm_result, %mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %var_sum = "stablehlo.reduce"(%diff_squared, %zero_f32) ({
