  %mean_x = "stablehlo.reduce"(%x_biased, %c0) {dimensions = %axes0} : (tensor<16x16xf32>, tensor<0xi64>) -> tensor<16x16xf32>
    // reduction with mean: sum over batch, then divide
  // sum over batch
  %sum_x = "stablehlo.reduce"(%x_biased, %c0) {dimensions = %axes0} : (tensor<16x16xf32>, tensor<0xi64>) -> tensor<16x16xf32>
  // count = 16
  %count = "stablehlo.constant"() {value = dense<16 : i64>} : () -> tensor<i64>
  // compute mean: sum / count
  %mean_x_div = "stablehlo.convert"(%count) : (tensor<i64>) -> tensor<f32>
  %mean_x = "stablehlo.divide"(%sum_x, %mean_x_div) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Compute variance: mean of squared differences
  %diff = "stablehlo.subtract"(%x_biased, "stablehlo.broadcast_in_dim"(%mean_x) {broadcast_dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>)
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %c0) {dimensions = %axes0} : (tensor<16x16xf32>, tensor<0xi64>) -> tensor<16x16xf32>
  // variance = sum / count
  %var = "stablehlo.divide"(%var_sum, %mean_x_div) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // stddev = sqrt(variance + epsilon)
