  %var_eps = "stablehlo.add"(%var, "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>)
  %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Normalize: (x - mean) / stddev
  %x_centered = "stablehlo.subtract"(%x_biased, "stablehlo.broadcast_in_dim"(%mean_x) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_norm = "stablehlo.divide"(%x_centered, "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 4: Swish activation: x * sigmoid(x)
  %sigmoid_x = "stablehlo.exponential"("stablehlo.negate"(%x_norm)) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %sigmoid_x = "stablehlo.divide"(
                "stablehlo.constant"() {value = dense<1.0 : f32>} : () -> tensor<f32>,
                "stablehlo.add"(
                  "stablehlo.exponential"("stablehlo.negate"(%x_norm)),
                  "stablehlo.constant"() {value = dense<1.0 : f32>} : () -> tensor<f32>
                )
