  // But better to use exponential and division for sigmoid
  %exp_neg_x = "stablehlo.exponential"("stablehlo.negate"(%x_norm)) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %one = "stablehlo.constant"() {value = dense<1.0 : f32>} : () -> tensor<f32>
