  %swish1 = "stablehlo.multiply"(%x_norm, %sigmoid_x_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 5: Multiply by %arg0 (multiply_weight)
  %multiply_weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_mul_weight = "stablehlo.multiply"(%swish1, %multiply_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 6: Swish again: x * sigmoid(x)
  // Recompute sigmoid(x) for second time
  %exp_neg_x2 = "stablehlo.exponential"("stablehlo.negate"(%x_mul_weight)) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %sigmoid_x3 = "stablehlo.divide"(%one, "stablehlo.add"(%exp_neg_x2, %one)) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  %sigmoid_x3_bcast = "stablehlo.broadcast_in_dim"(%sigmoid_x3) {broadcast_dimensions = array<i64: 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %final_output = "stablehlo.multiply"(%x_mul_weight, %sigmoid_x3_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Return final output
  return %final_output : tensor<16x16xf32>
}

