  func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
    // Step 1: Convolution parameters
    // %arg0: weight tensor of shape [7,8,3,3]
    // %arg1: bias tensor of shape [7]
    // Input: %arg2: shape [6,8,6,6]
    // Output shape: [6,7,4,4]

    // Step 2: Perform convolution
    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // Step 3: Add bias
    // Broadcast bias to match convolution output shape
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    // Note: The bias shape is [7], need to broadcast over batch and spatial dims
    // To broadcast bias over batch and spatial dims, we need to reshape bias to [1,7,1,1]
    %bias_reshape = "stablehlo.reshape"(%arg1) : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bias_bcast2 = "stablehlo.broadcast_in_dim"(%bias_reshape) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    // Alternatively, broadcast bias directly with proper dims
    // But for simplicity, do reshape then broadcast
    %conv_bias = "stablehlo.add"(%conv, %bias_bcast2) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Step 4: Apply HardSwish activation
    // HardSwish: x * relu6(x + 3) / 6
    // Implement relu6 as min(max(x + 3, 0), 6)
    // 1. Compute x + 3
    %const_three = "stablehlo.constant"() {value = dense<3.0> } : () -> tensor<f32>
    %x_plus_3 = "stablehlo.add"(%conv_bias, %const_three) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>
    // 2. relu6: min(max(x+3, 0), 6)
    %zero = "stablehlo.constant"() {value = dense<0.0> } : () -> tensor<f32>
    %six = "stablehlo.constant"() {value = dense<6.0> } : () -> tensor<f32>
    %relu6_max = "stablehlo.maximum"(%x_plus_3, %zero) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>
    %relu6 = "stablehlo.minimum"(%relu6_max, %six) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>
    // 3. Compute relu6(x+3)/6
    %relu6_div = "stablehlo.divide"(%relu6, %six) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>
    // 4. Multiply original x with relu6(x+3)/6
    %hardswish = "stablehlo.multiply"(%conv_bias, %relu6_div) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Step 5: ReLU activation
    %zero2 = "stablehlo.constant"() {value = dense<0.0> } : () -> tensor<f32>
    %output = "stablehlo.maximum"(%hardswish, %zero2) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // Return the final output
    return %output : tensor<6x7x4x4xf32>
  }
}

