// StableHLO program to compute pairwise squared Euclidean distances
// between rows of x and y: out[i,j] = sum_d (x[i,d] - y[j,d])^2

func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
  // Broadcast y to shape [4,2,5] for broadcasting over i and j
  %y_bcast = "stablehlo.broadcast_in_dim"(%y) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<2x5xf32>) -> tensor<2x4x5xf32>
  // Transpose y_bcast to shape [4,2,5] to align with x's shape
  // Since broadcast_in_dim with broadcast_dimensions={1} gives shape [2,4,5],
  // we need to permute axes to [4,2,5]
  %y_bcast_transposed = "stablehlo.transpose"(%y_bcast) {
    permutation = array<i64: 1, 0, 2>
  } : (tensor<2x4x5xf32>) -> tensor<4x2x5xf32>

  // Expand x to shape [4,1,5] for broadcasting over j
  %x_bcast = "stablehlo.broadcast_in_dim"(%x) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<4x5xf32>) -> tensor<4x1x5xf32>

  // Expand y to shape [1,2,5] for broadcasting over i
  %y_bcast2 = "stablehlo.broadcast_in_dim"(%y) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<2x5xf32>) -> tensor<2x5x1xf32>
  %y_bcast2_transposed = "stablehlo.transpose"(%y_bcast2) {
    permutation = array<i64: 2, 0, 1>
  } : (tensor<2x5x1xf32>) -> tensor<1x2x5xf32>

  // Now, broadcast x to shape [4,2,5]
  %x_bcast2 = "stablehlo.broadcast_in_dim"(%x_bcast) {
    broadcast_dimensions = array<i64: 1, 2>
  } : (tensor<4x1x5xf32>) -> tensor<4x2x5xf32>

  // Compute difference: diff = x_bcast2 - y_bcast2_transposed
  %diff = "stablehlo.subtract"(%x_bcast2, %y_bcast2_transposed) : (tensor<4x2x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>

  // Square the differences: diff_squared = diff * diff
  %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<4x2x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>

  // Reduce over dimension 2 (d) to sum the squared differences
  %out = "stablehlo.reduce"(%diff_squared, %c0) {
    ^bb0(%a: tensor<4x2x5xf32>, %b: tensor<4x2x5xf32>) -> (tensor<4x2x5xf32>) {
      %s = "stablehlo.add"(%a, %b) : (tensor<4x2x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>
      "stablehlo.return"(%s) : (tensor<4x2x5xf32>) -> ()
    }
  } : (tensor<4x2x5xf32>, tensor<f32>) -> tensor<4x2x5xf32> {
    dimensions = array<i64: 2>
  }

  // The result shape is [4,2], so reduce over dimension 2
  // But since reduce returns shape [4,2], we need to reduce over axis 2
  // The reduce operation as above reduces over axis 2, resulting in shape [4,2]
  // So, the final output is of shape [4,2]
  // Return the result
  return %out : tensor<4x2xf32>
}

