    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : tensor<6x16x16x7x7xf32>;

  // Step 2: Apply softmax along feature dimension (dimension 1)
  // For softmax, compute exp and sum over dimension 1, then divide
  %exp = "stablehlo.exponential"(%conv_out) : tensor<6x16x16x7x7xf32>
  // Sum over feature dimension (dim 1)
  %sum_exp = "stablehlo.reduce"(%exp, %c_zero) {
