  // Compute softmax
  %softmax = "stablehlo.divide"(%exp, %sum_bcast) : tensor<6x16x16x7x7xf32>

  // Step 3: MaxPool3D with kernel size 2x2x2, stride 2x2x2
  %pool1 = "stablehlo.reduce_window"(%softmax, %c_neg_inf) {
    window_dimensions = array<i64: 1, 1, 2, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2, 2>,
    base_dilations = array<i64: 1, 1, 1, 1, 1>,
