  // Tile bias to match batch size
  %bias_tiled = "stablehlo.broadcast_in_dim"(%bias_broadcasted) {
    broadcast_dimensions = array<i64: 1, 2, 3, 4>
  } : (tensor<16x1x1x1xf32>) -> tensor<6x16x16x7x7xf32>
  // Add bias
  %conv_bias = "stablehlo.add"(%conv, %bias_tiled) : (tensor<6x16x16x7x7xf32>, tensor<6x16x16x7x7xf32>) -> tensor<6x16x16x7x7xf32>

