// Computes the forward pass of the PyTorch module with parameters passed as arguments

func.func @main(%arg0: tensor<6x7x5xf32>, %arg1: tensor<6x6x8xf32>) -> tensor<6x7x20xf32> {
  // Define constants for convolution parameters
  %batch_size = constant 6 : i64
  %in_channels = constant 6 : i64
  %out_channels = constant 7 : i64
  %kernel_size = constant 5 : i64
  %length_in = constant 8 : i64
  %stride = constant 1 : i64
  %padding = constant 0 : i64
  %dilation = constant 3 : i64

  // Prepare the weight tensor (parameter)
  // %arg0 is the weight tensor: shape <6x7x5xf32>
  // For convolution, weight shape: [in_channels, out_channels, kernel_size]
  // But in StableHLO, the weight shape is [out_channels, in_channels, kernel_size]
  // So we need to transpose %arg0 to match [out_channels, in_channels, kernel_size]
  %weight_transposed = "stablehlo.transpose"(%arg0) {dimensions = array<i64: 1, 0, 2>} : (tensor<6x7x5xf32>) -> tensor<7x6x5xf32>

  // Compute output length for transposed convolution
  // Using formula: output_length = (input_length - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1
  %kernel_size_minus_one = "stablehlo.constant"() {value = 4 : i64} : () -> tensor<i64>
  %dilation_mul = "stablehlo.mul"(%dilation, %kernel_size_minus_one) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %dilation_mul_plus_one = "stablehlo.add"(%dilation_mul, "stablehlo.constant"() {value = 1 : i64}) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %input_length_minus_one = "stablehlo.sub"(%length_in, "stablehlo.constant"() {value = 1 : i64}) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %dilated_term = "stablehlo.mul"(%input_length_minus_one, %stride) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %padding_times_two = "stablehlo.mul"(%padding, "stablehlo.constant"() {value = 2 : i64}) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %output_length = "stablehlo.add"(%dilated_term, %dilation_mul_plus_one) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %output_length_final = "stablehlo.sub"(%output_length, %padding_times_two) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %output_length_plus_one = "stablehlo.add"(%output_length_final, "stablehlo.constant"() {value = 1 : i64}) : (tensor<i64>, tensor<i64>) -> tensor<i64>

  // Prepare the convolution dimension numbers
  // For 1D transposed convolution, dimension_numbers: input, kernel, output dims
  // Input dims: [b, f, l]
  // Kernel dims: [o, i, k]
  // Output dims: [b, f, l_out]
  // The dimension_numbers attribute: #stablehlo.conv<[b, f, l] x [o, i, k] -> [b, f, l_out]>
  // In MLIR, define as a constant attribute
  %dim_nums = #stablehlo.conv<[b, f, l] x [o, i, k] -> [b, f, l_out]>

  // Prepare the padding tensor: no padding for output shape, so set to zeros
  // padding: array<2xi64> with zeros
  %padding_array = "stablehlo.constant"() {value = dense<[0, 0]> : tensor<2xi64>} : () -> tensor<2xi64>

  // Call the convolution operation
  %conv_result = "stablehlo.convolution"(%arg1, %weight_transposed)
    {window_strides = array<i64: 1>, padding = %padding_array,
     lhs_dilation = array<i64: 1>, rhs_dilation = array<i64: 3>,
     dimension_numbers = #stablehlo.conv<[b, f, l] x [o, i, k] -> [b, f, l_out]>,
     feature_group_count = 1 : i64,
     batch_group_count = 1 : i64}
    : (tensor<6x6x8xf32>, tensor<7x6x5xf32>) -> tensor<6x7x20xf32>

  // Return the convolution result
  return %conv_result : tensor<6x7x20xf32>
}

