  // For B
  %B_masked = "stablehlo.select"(%mask, %arg1, %const_one) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Step 6: Perform matrix multiplication of the masked matrices
  // Use dot_general with batching dimensions empty, contracting over last dimension
  %dot_result = "stablehlo.dot_general"(%A_masked, %B_masked) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

