  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %clamped = "stablehlo.maximum"(%sub, %zero) : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

