  %div_const = "stablehlo.constant"() {value = dense<36.0> : tensor<f32>} : () -> tensor<f32>
  %mean_loss = "stablehlo.divide"(%loss, %div_const) : (tensor<f32>, tensor<f32>) -> tensor<f32>

