  // Initialize with 0.0
  %init = "stablehlo.constant"() {value = dense<0.0> } : () -> tensor<f32>
  // Reduce over all dimensions: 0 and 1
  %loss_sum = "stablehlo.reduce"(%clamped, %init) {
