    }
  } : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32> {
    dimensions = array<i64: 0, 1>
  }

  // Step 6: Compute the mean by dividing sum by total number of elements (36)
  %num_elements = "stablehlo.constant"() {value = dense<36.0>} : () -> tensor<f32>
  %mean_loss = "stablehlo.divide"(%loss_sum, %num_elements) : (tensor<f32>, tensor<f32>) -> tensor<f32>

