    %stride = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
    %padding = "stablehlo.constant"() {value = dense<[[4, 4]]] : tensor<1x2xi64>} : () -> tensor<1x2xi64>

