                  padding = dense<[[4, 4]]> : tensor<1x2xi64>
                } : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x7x9xf32>

    // Compute the sum of elements in each window to get the total sum for each output position
    // The output shape is (6,7,9), matching the expected output size
    // To get the average, divide by the window size (8)
    %window_size = "stablehlo.constant"() {value = dense<8> : tensor<i64>} : () -> tensor<i64>
    %divisor = "stablehlo.broadcast_in_dim"(%window_size) {broadcast_dimensions = array<i64: 0>} : (tensor<i64>) -> tensor<9>
