// StableHLO program implementing the described convolution operation
// Entry function: @main with specified signature
// Computes the forward pass of the PyTorch module as described

func.func @main(%arg0: tensor<16x16x5x9xf32>, %arg1: tensor<8x16x16x16xf32>) -> tensor<8x16x12x8xf32> {
  // %arg0: convolution weights, shape: [out_channels=16, in_channels=5, kernel_height=5, kernel_width=9]
  // %arg1: input tensor, shape: [batch=8, height=16, width=16, channels=16]
  // Output shape: [batch=8, height=12, width=8, channels=16]

  // Step 1: Transpose input to match NCHW format expected by convolution
  %input_transposed = "stablehlo.transpose"(%arg1) {permutation = dense<[0, 3, 1, 2]> : tensor<4xi64>} : (tensor<8x16x16x16xf32>) -> tensor<8x16x16x16xf32>

  // Step 2: Perform convolution
  // Convolution parameters:
  // window_strides = [1, 1]
  // padding = [[0, 0], [2, 2]] (to reduce height from 16 to 12, width from 16 to 8)
  // dilation = [1, 1]
  // dimension_numbers = conv<[b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]>
  // feature_group_count = 1
  %padding = "dense<[[0, 0], [2, 2]]>" : tensor<2x2xi64>
  %window_strides = "array<i64: 1, 1>" : tensor<2xi64>
  %lhs_dilation = "array<i64: 1, 1>" : tensor<2xi64>
  %rhs_dilation = "array<i64: 1, 1>" : tensor<2xi64>
  %dimension_numbers = #stablehlo.conv<[b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]>
  %feature_group_count = 1 : i64
  %batch_group_count = 1 : i64

  %conv_result = "stablehlo.convolution"(%input_transposed, %arg0) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = %dimension_numbers,
    feature_group_count = %feature_group_count,
    batch_group_count = %batch_group_count
  } : (tensor<8x16x16x16xf32>, tensor<16x5x5x9xf32>) -> tensor<8x16x12x8xf32>

  // Step 3: Transpose output back to NHWC format
  %output_transposed = "stablehlo.transpose"(%conv_result) {permutation = dense<[0, 2, 3, 1]> : tensor<4xi64>} : (tensor<8x16x12x8xf32>) -> tensor<8x12x8x16xf32>

  // Return the result
  return %output_transposed : tensor<8x12x8x16xf32>
}

// StableHLO program implementing the described convolution operation
// Entry function: @main(%arg0: tensor<16x16x5x9xf32>, %arg1: tensor<8x16x16x16xf32>) -> tensor<8x16x12x8xf32>

func.func @main(%arg0: tensor<16x16x5x9xf32>, %arg1: tensor<8x16x16x16xf32>) -> tensor<8x16x12x8xf32> {
  // Parameters:
  // %arg0: weight tensor of shape [5, 9, 16, 16]
  // %arg1: input tensor of shape [8, 16, 16, 16]
  // Output shape: [8, 16, 12, 8]

  // Define convolution parameters
  // window_strides = [1, 1]
  // padding = [[2, 2], [0, 0]] (to achieve output height=12, width=8)
  // lhs_dilation = [1, 1]
  // rhs_dilation = [1, 1]
  // dimension_numbers: input [b, h, w, f], kernel [kh, kw, in_c, out_c], output [b, h, w, f]
  // feature_group_count = 1
  // batch_group_count = 1

  %window_strides = array<i64: 1, 1> : tensor<2xi64>
  %padding = dense<[[2, 2], [0, 0]]> : tensor<2x2xi64>
  %lhs_dilation = array<i64: 1, 1> : tensor<2xi64>
  %rhs_dilation = array<i64: 1, 1> : tensor<2xi64>
  // dimension_numbers: input dims [b, h, w, f], kernel dims [kh, kw, in_c, out_c], output dims [b, h, w, f]
  #stablehlo.conv<[b, h, w, f] x [kh, kw, in_c, out_c] -> [b, h, w, f]> as dimension_numbers

  %result = "stablehlo.convolution"(%arg1, %arg0) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = #stablehlo.conv<[b, h, w, f] x [kh, kw, in_c, out_c] -> [b, h, w, f]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x16x16x16xf32>, tensor<5x9x16x16xf32>) -> tensor<8x12x8x16xf32>

  // Note: The output shape is [8, 12, 8, 16], but the function signature requires [8, 16, 12, 8]
  // We need to permute axes accordingly:
  // Current output shape: [b, h, w, f] = [8, 12, 8, 16]
  // Desired shape: [8, 16, 12, 8]
  // Permutation: axes [0, 3, 1, 2]

  %transposed = "stablehlo.transpose"(%result) {
    permutation = dense<[0, 3, 1, 2]> : tensor<4xi64>
  } : (tensor<8x12x8x16xf32>) -> tensor<8x16x12x8xf32>

  return %transposed : tensor<8x16x12x8xf32>
}

// StableHLO program implementing the forward pass of the described model
module {
  func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Step 1: matmul = "stablehlo.dot_general"(%arg3, %arg1)
    %dot_result = "stablehlo.dot_general"(%arg3, %arg1) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = []>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: add_value is %arg0 (tensor<7xf32>)
    // Broadcast add_value to shape of %dot_result (6x7)
    %add_value_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    // Step 3: Add the broadcasted add_value
    %add_result = "stablehlo.add"(%dot_result, %add_value_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: Sigmoid (Swish): sigmoid(x) * x
    // sigmoid(x) = 1 / (1 + exp(-x))
    %neg_x = "stablehlo.negate"(%add_result) : tensor<6x7xf32>
    %exp_neg_x = "stablehlo.exponential"(%neg_x) : tensor<6x7xf32>
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %denominator = "stablehlo.add"(%one_const, %exp_neg_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid = "stablehlo.divide"(%one_const, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Multiply sigmoid(x) * x
    %swish = "stablehlo.multiply"(%sigmoid, %add_result) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 5: Tanh activation
    %tanh1 = "stablehlo.tanh"(%swish) : tensor<6x7xf32>

    // Step 6: GELU activation
    // GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
    %sqrt2_const = "stablehlo.constant"() {value = dense<0x3F3504F3> : tensor<f32>} : () -> tensor<f32> // sqrt(2) ≈ 1.4142
    %x_div_sqrt2 = "stablehlo.divide"(%tanh1, %sqrt2_const) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    // erf(x / sqrt(2))
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // 1 + erf(...)
    %one_const2 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %one_plus_erf = "stablehlo.add"(%one_const2, %erf_x) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
    // 0.5 * x
    %half_const = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %x_times_half = "stablehlo.multiply"(%half_const, %tanh1) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
    // GELU output
    %gelu = "stablehlo.multiply"(%x_times_half, %one_plus_erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 7: Hardtanh with min -1, max 1
    %minus_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    // Clip at -1
    %clipped_min = "stablehlo.maximum"(%gelu, %minus_one) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Clip at 1
    %clipped_max = "stablehlo.minimum"(%clipped_min, %one) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // Return the final tensor
    return %clipped_max : tensor<6x7xf32>
  }
}

// StableHLO program implementing the forward pass of the described PyTorch model
// with parameters passed as arguments, producing output tensor<6x7xf32>.

func.func @main(%arg0: tensor<7xf32>,        // add_value
               %arg1: tensor<7x7xf32>,      // matmul.weight
               %arg2: tensor<7xf32>,        // matmul.bias
               %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> { // input
  // Step 1: matrix multiplication: x = matmul(input, weight^T)
  // Transpose weight to match dimensions
  %weight_T = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Perform dot_general: input (6x7), weight_T (7x7) -> (6x7)
  %dot = "stablehlo.dot_general"(%arg3, %weight_T) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias to shape (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 0, 1>
  } : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_bias = "stablehlo.add"(%dot, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Step 2: Swish activation: sigmoid(x) * x
  // Sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = "stablehlo.negate"(%add_bias) : tensor<6x7xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : tensor<6x7xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %denominator = "stablehlo.add"(%one, %exp_neg_x) : tensor<6x7xf32>
  %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
  // Swish: sigmoid(x) * x
  %swish = "stablehlo.multiply"(%sigmoid, %add_bias) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Step 3: Tanh activation
  %tanh = "stablehlo.tanh"(%swish) : tensor<6x7xf32>
  // Step 4: GELU activation
  // GELU approximation: 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
  // Compute x^3
  %x_cubed = "stablehlo.power"(%tanh, %one) {b = dense<3.0> : tensor<f32>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  // Compute coefficient: √(2/π)
  %sqrt_two_over_pi = "stablehlo.constant"() {value = dense<0.7978845608> : tensor<f32>} : () -> tensor<f32>
  // 0.044715 * x^3
  %coeff = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>} : () -> tensor<f32>
  %x_cubed_scaled = "stablehlo.multiply"(%coeff, %x_cubed) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  // x + 0.044715 * x^3
  %x_plus = "stablehlo.add"(%tanh, %x_cubed_scaled) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Multiply by sqrt_two_over_pi
  %inner = "stablehlo.multiply"(%sqrt_two_over_pi, %x_plus) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // tanh of the inner
  %tanh_inner = "stablehlo.tanh"(%inner) : tensor<6x7xf32>
  // 1 + tanh(...)
  %one_plus = "stablehlo.add"(%one, %tanh_inner) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Final GELU: 0.5 * x * (1 + tanh(...))
  %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %x_times = "stablehlo.multiply"(%half, %tanh) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %gelu = "stablehlo.multiply"(%x_times, %add_bias) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Step 5: Hardtanh activation with min -1, max 1
  // Clamp between -1 and 1
  %minus_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
  %one_clamped = "stablehlo.maximum"(%gelu, %minus_one) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
  %maxed = "stablehlo.minimum"(%one_clamped, %one) : (tensor<f32>, tensor<f32>) -> tensor<6x7xf32>
  // Output
  return %maxed : tensor<6x7xf32>
}

