// StableHLO program implementing the forward pass of the described PyTorch model
// Signature: func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32>

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Step 1: matmul = %arg1 * %arg3^T
  // Transpose %arg3 to align dimensions for matmul
  %perm = dense<[1, 0]> : tensor<6x7xf32> -> tensor<7x6xf32>
  %arg3_T = "stablehlo.transpose"(%arg3) {permutation = dense<[1, 0]> : tensor<2xi64>} : (tensor<6x7xf32>) -> tensor<7x6xf32>

  // Perform dot_general for matrix multiplication
  %dot_dims = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  %matmul = "stablehlo.dot_general"(%arg1, %arg3_T) {dot_dimension_numbers = %dot_dims} : (tensor<7x7xf32>, tensor<7x6xf32>) -> tensor<7x6xf32>

  // Step 2: Add %arg0 (add_value) to matmul result
  // Broadcast %arg0 to shape of %matmul (7x6)
  // Since %arg0 is shape<7xf32>, need to broadcast to match shape<7x6>
  // Broadcast in dimension 1 (columns)
  %bcast_add_value = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = dense<[0]> : tensor<1xi64>
  } : (tensor<7xf32>) -> tensor<7x1xf32>
  // Expand to shape<7x6> by broadcasting along second dimension
  %bcast_add_value_expanded = "stablehlo.broadcast_in_dim"(%bcast_add_value) {
    broadcast_dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<7x1xf32>) -> tensor<7x6xf32>

  // Add the broadcasted add_value to matmul result
  %add = "stablehlo.add"(%matmul, %bcast_add_value_expanded) : (tensor<7x6xf32>, tensor<7x6xf32>) -> tensor<7x6xf32>

  // Step 3: Apply Swish activation: sigmoid * x
  // Sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = "stablehlo.negate"(%add) : tensor<7x6xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : tensor<7x6xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %denominator = "stablehlo.add"(%one, %exp_neg_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // Element-wise multiply sigmoid * x
  %swish = "stablehlo.multiply"(%sigmoid, %add) : (tensor<7x6xf32>, tensor<7x6xf32>) -> tensor<7x6xf32>

  // Step 4: Tanh activation
  %tanh = "stablehlo.tanh"(%swish) : tensor<7x6xf32>

  // Step 5: GELU activation
  // GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = "stablehlo.constant"() {value = dense<1.4142135623730951> : tensor<f32>} : () -> tensor<f32>
  %x_div_sqrt2 = "stablehlo.divide"(%tanh, %sqrt2) : (tensor<7x6xf32>, tensor<f32>) -> tensor<7x6xf32>
  // Compute erf(x / sqrt(2))
  %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<7x6xf32>) -> tensor<7x6xf32>
