    // Batch dims: 0,1; Contract dims: 2,3
    %dot_dim_nums = #stablehlo.dot<lhs_batching_dimensions = [0,1], rhs_batching_dimensions = [0,1], lhs_contracting_dimensions = [2,3], rhs_contracting_dimensions = [2,3]>
    %matmul = "stablehlo.dot_general"(%arg0, %K_T) {dot_dimension_numbers = %dot_dim_nums} : tensor<6x6x7x8xf32>, tensor<6x6x7x8xf32> -> tensor<6x6x7x8xf32>

    // Step 3: Scale by 1 / sqrt(d_k), where d_k=8
    // Compute 1 / sqrt(8)
    %sqrt_const = "stablehlo.constant"() {value = dense<0x3F3504F3> } : () -> tensor<f32> // 1 / sqrt(8) ≈ 0.3535534
    // Alternatively, compute dynamically:
    // %d_k = constant dense<8.0> : tensor<f32>
    // %d_k_sqrt = "stablehlo.sqrt"(%d_k) : tensor<f32>
    // %scale = "stablehlo.divide"() { numerator = dense<1.0> : tensor<f32>, denominator = %d_k_sqrt } : () -> tensor<f32>
    // But for simplicity, use constant
    %scale = %sqrt_const

