    // For scaled dot product, typically, K is transposed over the last two dims
    // So, transpose K over dims 2 and 3
    %K_T = "stablehlo.transpose"(%arg1) {permutation = array<i64: 0, 1, 3, 2>} : (tensor<6x6x7x8xf32>) -> tensor<6x6x8x7xf32>

