      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0,1], rhs_batching_dimensions = [0,1], lhs_contracting_dimensions = [2], rhs_contracting_dimensions = [3]>
    } : (tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32>) -> tensor<6x6x7x7>

    // Step 3: Scale the dot product by 1 / sqrt(8)
    %scale_const = "stablehlo.constant"() {value = dense<0x3f800000> } : () -> tensor<f32> // 1.0 in hex
    // Compute 1 / sqrt(8)
    %sqrt_8 = "stablehlo.exponential"(%scale_const) : (tensor<f32>) -> tensor<f32> // e^{0} = 1, but we need sqrt(8)
    // Instead, define constant for sqrt(8)
    %sqrt8_const = "stablehlo.constant"() {value = dense<0x41800000> } : () -> tensor<f32> // 8.0 in hex
    %sqrt8 = "stablehlo.sqrt"(%sqrt8_const) : (tensor<f32>) -> tensor<f32>
    %inv_sqrt8 = "stablehlo.divide"(%scale_const, %sqrt8) : (tensor<f32>, tensor<f32>) -> tensor<f32>
