    // Use broadcast_in_dim
    %scale_factor = "stablehlo.broadcast_in_dim"(%inv_sqrt8) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<f32>) -> tensor<6x6x7x7>
    // Actually, broadcasting scalar to shape [6,6,7,7]
    // But since scalar, broadcasting is automatic, or we can do:
    // For simplicity, just do element-wise multiply with scalar broadcasted
    %scaled_QK = "stablehlo.multiply"(%dot_QK, %scale_factor) : (tensor<6x6x7x7>, tensor<6x6x7x7>) -> tensor<6x6x7x7>

