    } : (tensor<6x6x7x7>, tensor<f32>) -> tensor<6x6x7x7>
    // Initialize zero tensor for reduction
    %c_zero = "stablehlo.constant"() {value = dense<0x00000000>} : () -> tensor<f32>
    // sum_exp shape: [6,6,7,7]
    // To compute softmax: exp / sum over last dim
