// StableHLO program to compute the forward pass of the described PyTorch model
// with inputs: %arg0 and %arg1, both tensor<12x12xf32>
// Output: tensor<f32> representing the model's output

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Step 1: Compute log(%arg0)
  %log_pred = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 2: Compute kl_div = torch.nn.functional.kl_div(log(predictions), targets, reduction='batchmean')
  // According to the formula: kl_div = sum(targets * (log(targets) - log(predictions))) / batch_size
  // But in the code, it uses torch.nn.functional.kl_div(log(predictions), targets, reduction='batchmean')
  // which is equivalent to sum over batch of targets * (log(targets) - log(predictions)) / batch_size
  // For simplicity, we implement: sum(targets * (log(targets) - log(predictions))) / batch_size

  // Step 3: Compute log(%arg1)
  %log_target = "stablehlo.log"(%arg1) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 4: Compute (log(targets) - log(predictions))
  %diff_log = "stablehlo.subtract"(%log_target, %log_pred) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 5: Element-wise multiply targets and diff_log
  %mul_targets_diff = "stablehlo.multiply"(%arg1, %diff_log) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 6: Sum over all elements to get total sum
  // Use reduce with addition over all elements
  %init_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum_all = "stablehlo.reduce"(%mul_targets_diff, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Step 7: Compute batch size (number of elements in batch)
  // Since input shape is 12x12, batch size is 12*12=144
  // But in the original code, batch size is 6*2=12, but here inputs are 12x12
  // So total elements: 12*12=144
  // For reduction, sum over all elements, then divide by total number of elements
  // So, compute total number of elements
  %total_elements = "stablehlo.constant"() {value = dense<144.0> : tensor<f32>} : () -> tensor<f32>

  // Step 8: Divide sum by total number of elements to get mean
  %kl_div = "stablehlo.divide"(%sum_all, %total_elements) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  // Return the result
  return %kl_div : tensor<f32>
}

// StableHLO program to compute the forward pass of the described model
// which calculates the KL divergence between two distributions.
// Input tensors: %arg0 and %arg1, both of shape 12x12xf32
// Output: scalar f32

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Step 1: Compute log of predictions: log(%arg0)
  %log_pred = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 2: Compute KL divergence: kl_div = torch.nn.functional.kl_div(log_predictions, targets, reduction='batchmean')
  // According to the description, reduction='batchmean' divides sum by batch size (here, 6*2=12)
  // So, sum over all elements, then divide by 12.
  // First, compute sum of element-wise product: log_pred * %arg1
  %mul_log_target = "stablehlo.multiply"(%log_pred, %arg1) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum all elements in %mul_log_target
