  // Initialize reduction with zero
  %zero_f32 = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>
  // Reduce over dimensions 0 and 1
  %reduced_sum = "stablehlo.reduce"(%mul_log_target, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): (tensor<f32>, tensor<f32>) {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
