    }
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide sum by batch size (12)
  %batch_size = "stablehlo.constant"() {value = dense<12 : i64>} : () -> tensor<i64>
  // Convert batch size to float for division
  %batch_size_f = "stablehlo.convert"(%batch_size) : (tensor<i64>) -> tensor<f32>
  %sum_div = "stablehlo.divide"(%reduced_sum, %batch_size_f) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  // Final output: scalar tensor of shape () with the KL divergence value
  return %sum_div : tensor<f32>
}

// StableHLO program to compute the forward pass of the described model
// which calculates the KL divergence between two distributions.
// Input: %arg0, %arg1 of shape 12x12xf32
// Output: scalar f32

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Step 1: Compute log of predictions (%arg0)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %log_predictions = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 2: Compute KL divergence: "stablehlo.kl_div" equivalent
  // Since stablehlo does not have kl_div, implement as:
  // sum over all elements: predictions * (log(predictions) - targets)
  // But the original code uses torch.nn.functional.kl_div(log(predictions), targets, reduction='batchmean')
  // which is equivalent to: mean over batch of sum over features of predictions * (log(predictions) - targets)
  // For simplicity, compute element-wise: predictions * (log(predictions) - targets)
  // and then reduce sum over all elements, then divide by total number of elements (144)

  // Step 3: Compute (log_predictions - targets)
  %diff_log_target = "stablehlo.subtract"(%log_predictions, %arg1) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 4: Element-wise multiply predictions * (log(predictions) - targets)
  %pred_mul_diff = "stablehlo.multiply"(%arg0, %diff_log_target) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Step 5: Reduce sum over all elements
  // Initialize zero tensor scalar
  %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // Define reduction body: add
  ^bb0(%a: tensor<f32>, %b: tensor<f32>):
    %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  // Perform reduce over all dimensions (0 and 1)
  %sum_all = "stablehlo.reduce"(%pred_mul_diff, %init) ({^bb0(%a, %b): tensor<f32>, tensor<f32>: %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32> "stablehlo.return"(%s) : (tensor<f32>) -> () }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Step 6: Compute mean by dividing sum by total number of elements (144)
  %total_elements = "stablehlo.constant"() {value = dense<144.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.divide"(%sum_all, %total_elements) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  // Return the scalar result
  return %mean : tensor<f32>
}

