// The function takes a tensor<6x7xf32> as input and returns the same shape tensor after applying ELU.
// The ELU function is implemented as: elu(x) = max(0, x) + min(0, alpha * (exp(x) - 1))
// with alpha = 1.0 (constant).

func.func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
