  %exp_x = "stablehlo.exponential"(%arg0) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute alpha * (exp(x) - 1)
  %exp_minus_one = "stablehlo.subtract"(%exp_x, %c_one) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  %alpha_times_exp_minus_one = "stablehlo.multiply"(%alpha, %exp_minus_one) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute max(0, x)
