  %exp_min = "stablehlo.exponential" %x_min_zero : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 6: Compute exp(min(x, 0)) - 1
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %exp_min_minus_one = "stablehlo.subtract" %exp_min, %one : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Step 7: Add max(x, 0) + (exp(min(x, 0)) - 1)
  %elu = "stablehlo.add" %x_max_zero, %exp_min_minus_one : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Return the result
  return %elu : tensor<6x7xf32>
}

