// StableHLO program to compute the forward pass of the described PyTorch model
// with inputs: predictions and targets, both tensors<12x12xf32>.
// The computation performs: torch.nn.functional.kl_div(torch.log(predictions), targets, reduction='batchmean').
// Since reduction='batchmean', the output is the mean over the batch dimension (dim=0).
// The implementation computes log(predictions), then kl_div with targets, then reduces over batch dimension (dim=0).

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions): log(%arg0)
  %log_predictions = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute element-wise division: log(predictions) - targets
  // But kl_div in PyTorch computes: F.kl_div(input, target), where input is log(predictions),
  // and target is targets.
  // So, we need to compute the element-wise difference: log(predictions) - targets
  %diff = "stablehlo.subtract"(%log_predictions, %arg1) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum over all elements to get total sum
  // But reduction='batchmean' in PyTorch means mean over batch dimension (dim=0).
  // So, we need to reduce over batch dimension (dim=0), then compute mean.
  // First, sum over batch dimension (dim=0)
  %sum_over_batch = "stablehlo.reduce"(%diff, %c0) {
    ^bb0(%a: tensor<12x12xf32>, %b: tensor<12x12xf32>) -> tensor<12x12xf32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>
      "stablehlo.return"(%s) : (tensor<12x12xf32>) -> ()
    }
  } {dimensions = array<i64: 0>} : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute mean over batch dimension (dim=0): divide sum by batch size (6*2=12)
  %batch_size = constant dense<12> : tensor<i64>
  %batch_size_f32 = "stablehlo.convert"(%batch_size) : (tensor<i64>) -> tensor<f32>
  %sum_over_batch_f32 = "stablehlo.cast"(%sum_over_batch) : (tensor<12x12xf32>) -> tensor<12x12xf32>
  %mean = "stablehlo.divide"(%sum_over_batch_f32, %batch_size_f32) : (tensor<12x12xf32>, tensor<f32>) -> tensor<12x12xf32>

  // Now, reduce over all elements to get scalar output
  // First, reduce over all dimensions: axes = [0,1]
  %axes = constant dense<[0,1]> : tensor<2xi64>
  %total_sum = "stablehlo.reduce"(%mean, %c0) {
    ^bb0(%a: tensor<12x12xf32>, %b: tensor<12x12xf32>) -> tensor<12x12xf32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>
      "stablehlo.return"(%s) : (tensor<12x12xf32>) -> ()
    }
  } {dimensions = array<i64: 0,1>} : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum over all elements to get scalar
  %scalar_sum = "stablehlo.reduce"(%total_sum, %c0) {
    ^bb0(%a: tensor<12x12xf32>, %b: tensor<12x12xf32>) -> tensor<12x12xf32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>
      "stablehlo.return"(%s) : (tensor<12x12xf32>) -> ()
    }
  } {dimensions = array<i64: 0,1>} : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Now, sum over all elements again to get scalar
  %final_sum = "stablehlo.reduce"(%scalar_sum, %c0) {
    ^bb0(%a: tensor<12x12xf32>, %b: tensor<12x12xf32>) -> tensor<12x12xf32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>
      "stablehlo.return"(%s) : (tensor<12x12xf32>) -> ()
    }
  } {dimensions = array<i64: 0,1>} : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Extract scalar value from tensor
  // Since the tensor is scalar, we can use "stablehlo.get_element" (not in the spec, but for illustration)
  // Alternatively, we can assume the tensor is scalar and just return it.
  // For safety, we can use "stablehlo.collapse_shape" to get scalar
