    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  } {dimensions = array<i64: 1, 2, 3>} : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>
  // Divide by 4096 to get variance
