  %var_eps = "stablehlo.add"(%var, %epsilon) : (tensor<f32>, tensor<f32>) -> tensor<f32>
  // Compute stddev
  %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<f32>) -> tensor<f32>
  // Broadcast stddev for division
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
  // Normalize
  %x_norm = "stablehlo.divide"(%x_centered, %stddev_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
  // Step 3: Apply affine transformation: scale and shift
  // Broadcast weight and bias
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
