  %y = "stablehlo.add"(%x_scaled, %bias_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
  // Return the result
  "stablehlo.return"(%y) : (tensor<14x16x16x16xf32>) -> ()
}

// StableHLO program implementing a GELU activation on input tensor of shape 6x7
module {
  func.func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Step 1: Compute x^3
    %x_squared = "stablehlo.multiply" %arg0, %arg0 : tensor<6x7xf32>
    %x_cubed = "stablehlo.multiply" %x_squared, %arg0 : tensor<6x7xf32>

    // Step 2: Compute 0.044715 * x^3
    %const_0_044715 = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>} : () -> tensor<f32>
    %scaled_x_cubed = "stablehlo.multiply" %const_0_044715, %x_cubed : tensor<f32>

    // Step 3: Compute x + 0.044715 * x^3
    %x_plus = "stablehlo.add" %arg0, %scaled_x_cubed : tensor<6x7xf32>

    // Step 4: Compute 0.79788456 * (x + 0.044715 * x^3)
    %const_0_79788456 = "stablehlo.constant"() {value = dense<0.79788456> : tensor<f32>} : () -> tensor<f32>
    %inner = "stablehlo.multiply" %const_0_79788456, %x_plus : tensor<6x7xf32>

    // Step 5: Compute tanh of the inner
    // Since StableHLO does not have tanh directly, implement as (exp(2x) - 1) / (exp(2x) + 1)
    // But for simplicity, use exp and algebraic manipulation:
    // tanh(x) = 1 - 2 / (exp(2x) + 1)
    %two = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
    %two_x = "stablehlo.multiply" %two, %inner : tensor<6x7xf32>
    %exp_2x = "stablehlo.exponential" %two_x : tensor<6x7xf32>
    %denominator = "stablehlo.add" %exp_2x, "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : tensor<6x7xf32>
    %recip = "stablehlo.divide" "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} , %denominator : tensor<6x7xf32>
    %tanh_x = "stablehlo.subtract" "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} , "stablehlo.multiply" %recip, "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : tensor<6x7xf32>
    // Wait, the above is complicated; better to implement tanh directly as (exp(2x) - 1)/(exp(2x) + 1)
    // Let's do that:
    // Recompute tanh as (exp(2x) - 1) / (exp(2x) + 1)
    // So, define numerator and denominator
    // numerator = exp(2x) - 1
    // denominator = exp(2x) + 1
    // Then tanh_x = numerator / denominator

    // Recompute:
    // numerator
    %exp_2x_alt = "stablehlo.exponential" %two_x : tensor<6x7xf32>
    %numerator = "stablehlo.subtract" %exp_2x_alt, "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : tensor<6x7xf32>
    // denominator
    %denominator_alt = "stablehlo.add" %exp_2x_alt, "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : tensor<6x7xf32>
    // tanh
    %tanh = "stablehlo.divide" %numerator, %denominator_alt : tensor<6x7xf32>

    // Step 6: Compute 0.5 * (tanh + 1)
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %tanh_plus_one = "stablehlo.add" %tanh, %one : tensor<6x7xf32>
    %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %gelu_approx = "stablehlo.multiply" %half, %tanh_plus_one : tensor<6x7xf32>

    // Step 7: Final output: x * gelu_approx
    %result = "stablehlo.multiply" %arg0, %gelu_approx : tensor<6x7xf32>

    return %result : tensor<6x7xf32>
  }
}

// StableHLO program implementing the forward pass of the described GroupNorm model
module {
  func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32> {
    // Constants for parameters
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %minus_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
    %half = "stablehlo.constant"() {value = dense<0x3F000000> : tensor<f32>} : () -> tensor<f32> // 0.5
    %eps = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>

    // Extract shape info
    // shape of input tensor: (14, 16, 16, 16)
    // We need to compute mean and variance over axes [2,3]
    // axes to reduce: [2,3]
    %axes = "stablehlo.constant"() {value = dense<[2, 3]> : tensor<2xi64>} : () -> tensor<2xi64>

    // Compute mean over axes [2,3]
    %init_mean = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %mean = "stablehlo.reduce"(%arg2, %init_mean) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): (tensor<f32>) {
        %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%sum) : (tensor<f32>) -> ()
      }
    }) {dimensions = %axes} : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>
    // Now compute sum over axes [2,3]
    %sum_over_axes = %mean
    // Compute number of elements in reduction axes: 16*16=256
    %num_elements = "stablehlo.constant"() {value = dense<256> : tensor<i64>} : () -> tensor<i64>
    // Compute mean: mean = sum / num_elements
    %mean_div = "stablehlo.divide"(%sum_over_axes, "stablehlo.convert"(%num_elements) : tensor<i64> -> tensor<f32>) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Compute variance
    // Broadcast mean to shape of input
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0>} : (tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // Compute (x - mean)
    %diff = "stablehlo.subtract"(%arg2, %mean_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // Square the difference
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // Sum squared differences over axes [2,3]
    %sum_sq = "stablehlo.reduce"(%diff_sq, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): (tensor<f32>) {
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
      }
    }) {dimensions = %axes} : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>
    // Compute variance = sum_sq / num_elements
    %var = "stablehlo.divide"(%sum_sq, "stablehlo.convert"(%num_elements) : tensor<i64> -> tensor<f32>) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Compute stddev = sqrt(variance + epsilon)
    %var_plus_eps = "stablehlo.add"(%var, "stablehlo.convert"(%eps) : tensor<f32>) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %stddev = "stablehlo.sqrt"(%var_plus_eps) : tensor<f32>

    // Broadcast mean and stddev to input shape
    %mean_bcast_full = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0>} : (tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<14x16x16x16xf32>

    // Normalize: (x - mean) / stddev
    %x_minus_mean = "stablehlo.subtract"(%arg2, %mean_bcast_full) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    %normalized = "stablehlo.divide"(%x_minus_mean, %stddev_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Reshape normalized to (14, 16, 16, 16) - already shape
    // Now multiply by weight (scale)
    %scale_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<14x16x16x16xf32>
    %scaled = "stablehlo.multiply"(%normalized, %scale_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Add bias
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<14x16x16x16xf32>
    %output = "stablehlo.add"(%scaled, %bias_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Return the normalized output
    "stablehlo.return"(%output) : (tensor<14x16x16x16xf32>) -> ()
  }
}

