  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_output = "stablehlo.add"(%scaled, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

