// StableHLO program to normalize each row of a 3x8 tensor to unit L2 norm
module {
  func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
    // Step 1: Compute x^2 element-wise
    %x_squared = "stablehlo.multiply" %x, %x : tensor<3x8xf32>

    // Step 2: Reduce along dimension 1 (columns) to sum squares per row
    %init = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>
    %sum_squares = "stablehlo.reduce"(%x_squared, %init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): (tensor<f32>) {
        %s = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %s : (tensor<f32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3xf32>

    // Step 3: Compute sqrt of sum of squares to get L2 norm per row
    %l2_norm = "stablehlo.sqrt" %sum_squares : tensor<3xf32>

    // Step 4: Broadcast l2_norm to shape 3x8 for division
    %broadcast_dims = array<i64: 1>
    %l2_norm_broadcast = "stablehlo.broadcast_in_dim" %l2_norm {broadcast_dimensions = %broadcast_dims} : tensor<3xf32> -> tensor<3x8xf32>

    // Step 5: Divide original x by the broadcasted L2 norm
    %out = "stablehlo.divide" %x, %l2_norm_broadcast : tensor<3x8xf32>

    // Return the normalized tensor
    return %out : tensor<3x8xf32>
  }
}

