  // The reduction axes: dimension 1 (columns)
  %axes = "stablehlo.constant"() {value = dense<[1]> : tensor<1xi64>} : () -> tensor<1xi64>
  %result = "stablehlo.reduce"(%cmp_i32, %zero) {
