// StableHLO program to compute the forward pass of a Cross Entropy Loss model
// with inputs: predictions tensor<6x7xf32> and targets tensor<6xi64>
// Output: tensor<f32> (scalar loss value)

func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
  // Step 1: Convert targets from i64 to f32
  %targets_f32 = "stablehlo.convert"(%arg1) : (tensor<6xi64>) -> tensor<6xf32>

  // Step 2: Compute max over predictions for numerical stability
  // Initialize reduction with -inf
  %minus_inf = "stablehlo.constant"() {value = dense<0xFF800000> : tensor<f32>} : () -> tensor<f32>
  // Reduce max over dimension 1 (columns)
  %max_pred = "stablehlo.reduce"(%arg0, %minus_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %max = "stablehlo.maximum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%max) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Step 3: Broadcast max for subtraction
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_pred) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Step 4: Subtract max from predictions for numerical stability
  %pred_minus_max = "stablehlo.subtract"(%arg0, %max_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 5: Compute exp(predictions - max)
  %exp_pred = "stablehlo.exponential"(%pred_minus_max) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 6: Sum exp over classes (dimension 1)
  %zero_f32 = "stablehlo.constant"() {value = dense<0x00000000> : tensor<f32>} : () -> tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_pred, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Step 7: Compute log(sum_exp) for each sample
  %log_sum_exp = "stablehlo.log"(%sum_exp) : (tensor<6xf32>) -> tensor<6xf32>

  // Step 8: Gather the predicted scores for the true classes
  // For each sample, get the predicted score at the target class index
  // First, create an index tensor for batch indices: [0,1,2,3,4,5]
  %batch_indices = "stablehlo.iota"() {iota_dimension = 0} : () -> tensor<6xi32>
  // Convert batch indices to f32 for gather
  %batch_indices_f32 = "stablehlo.convert"(%batch_indices) : (tensor<6xi32>) -> tensor<6xf32>
  // Expand dims to match predictions shape for gather
  // But StableHLO does not have gather, so simulate gather via element-wise indexing
  // Alternative: use "stablehlo.compare" to create masks and select
  // For simplicity, perform a loop-like operation: create a tensor of indices and select
  // Since MLIR/StableHLO does not have direct gather, we can do a workaround:
  // Create a tensor of shape 6x7 with class indices
  %class_indices = "stablehlo.iota"() {iota_dimension = 1} : () -> tensor<7xi32>
  // Broadcast class_indices to shape 6x7
  %class_indices_broadcast = "stablehlo.broadcast_in_dim"(%class_indices) {broadcast_dimensions = array<i64: 0>} : (tensor<7xi32>) -> tensor<6x7xi32>
  // Expand targets to shape 6x7
  %targets_expanded = "stablehlo.broadcast_in_dim"(%targets_f32) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Convert targets to i32 for comparison
  %targets_i32 = "stablehlo.convert"(%targets_f32) : (tensor<6xf32>) -> tensor<6xi32>
  // Broadcast targets to shape 6x7
  %targets_broadcast = "stablehlo.broadcast_in_dim"(%targets_i32) {broadcast_dimensions = array<i64: 1>} : (tensor<6xi32>) -> tensor<6x7xi32>
  // Create mask where class_indices_broadcast == targets_broadcast
  %mask = "stablehlo.compare"(%class_indices_broadcast, %targets_broadcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<compare_type SIGNED>} : (tensor<6x7xi32>, tensor<6x7xi32>) -> tensor<6x7xi1>
  // Convert mask to f32
  %mask_f32 = "stablehlo.convert"(%mask) : (tensor<6x7xi1>) -> tensor<6x7xf32>
  // Multiply predictions with mask to zero out non-target classes
  %pred_masked = "stablehlo.multiply"(%arg0, %mask_f32) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Sum over classes to get the predicted scores at target classes
  %pred_scores = "stablehlo.reduce"(%pred_masked, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Step 9: Compute negative log likelihood: -log(pred_scores)
  %neg_pred_scores = "stablehlo.negate"(%pred_scores) : (tensor<6xf32>) -> tensor<6xf32>
  %log_pred_scores = "stablehlo.log"(%pred_scores) : (tensor<6xf32>) -> tensor<6xf32>

  // Step 10: Compute loss = mean of negative log likelihoods
  // Sum all values
  %sum_loss = "stablehlo.reduce"(%neg_pred_scores, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 0>} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>
  // Compute mean: sum / number of samples (6)
  %num_samples = "stablehlo.constant"() {value = dense<6 : i64>} : () -> tensor<i64>
  %num_samples_f32 = "stablehlo.convert"(%num_samples) : (tensor<i64>) -> tensor<f32>
  %loss = "stablehlo.divide"(%sum_loss, %num_samples_f32) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  // Return the scalar loss as a tensor of shape ()
  return %loss : tensor<f32>
}

