  %arg1_T = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Perform dot_general (matmul)
  %matmul_result = "stablehlo.dot_general"(%arg5, %arg1_T) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: Add bias: %add_bias = %matmul_result + %arg2
  %add_bias = "stablehlo.add"(%matmul_result, %arg2) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>

  // Step 3: Apply Hardtanh: clamp between -1 and 1
  // hardtanh_min = constant -1.0
  %const_neg_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
  // hardtanh_max = constant 1.0
  %const_one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  // clip lower: max(%add_bias, -1)
  %max_lower = "stablehlo.maximum"(%add_bias, %const_neg_one) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // clip upper: min(%max_lower, 1)
  %clamped = "stablehlo.minimum"(%max_lower, %const_one) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Step 4: Apply Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp_x = "stablehlo.exponential"(%clamped) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %softplus = "stablehlo.log_plus_one"(%clamped) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // tanh(softplus(x))
  %tanh_sp = "stablehlo.tanh"(%softplus) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Mish: x * tanh(softplus(x))
  %mish = "stablehlo.multiply"(%clamped, %tanh_sp) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 5: Layer normalization (GroupNorm)
  // Compute mean and variance over channels (dim=1)
  // For mean: reduce sum over dim=1, then divide by 16
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // sum over dim=1
  %sum_channels = "stablehlo.reduce"(%mish, %zero) {
    dimensions = array<i64: 1>
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  // Compute mean: divide sum by 16
  %div_const = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.divide"(%sum_channels, %div_const) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // Expand mean to shape [16,16] for broadcasting
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
  // Subtract mean
  %centered = "stablehlo.subtract"(%mish, %mean_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Compute variance: sum of squared deviations
  %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %sum_sq = "stablehlo.reduce"(%centered_sq, %zero) {
    dimensions = array<i64: 1>
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
