  %var = "stablehlo.divide"(%sum_sq, %div_const) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // Compute stddev = sqrt(variance + epsilon)
  %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
  %var_eps = "stablehlo.add"(%var, %epsilon) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<16xf32>) -> tensor<16xf32>
  // Broadcast stddev for division
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
  // Normalize: (x - mean) / stddev
  %normalized = "stablehlo.divide"(
                  "stablehlo.subtract"(%centered, %mean_broadcast),
                  %stddev_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 6: Scale and shift by groupnorm weight and bias
  // groupnorm.weight: %arg3, shape (16,)
  // groupnorm.bias: %arg4, shape (16,)
  // Broadcast weight and bias
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
  // Apply scale and shift
  %scaled = "stablehlo.multiply"(%normalized, %gn_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %shifted = "stablehlo.add"(%scaled, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Return the final tensor
  return %shifted : tensor<16x16xf32>
}

