    } : (tensor<6x7x8x8xf32>, tensor<7x7x4x4xf32>) -> tensor<6x7x17x17xf32>

    // Step 2: Broadcast bias to match convolution output shape
    // bias shape: (7,)
    // convolution output shape: (6,7,17,17)
    // Broadcast bias over batch and spatial dims
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {
