    // Step 4: Apply tanh activation
    %tanh_out = "stablehlo.tanh"(%sub_bias) : tensor<6x7x17x17xf32> -> tensor<6x7x17x17xf32>

    // Return the result
    return %tanh_out : tensor<6x7x17x17xf32>
  }
