    lhs_dilation = array<i64: 1>,
    rhs_dilation = array<i64: 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x6x7x7xf32>, tensor<6x7x3x3xf32>) -> tensor<16x7x15x15xf32>

