  // Reduce over dims 2 and 3 with 'maximum' as initial value (since mean is sum / count, but no mean op, use sum then divide)
  // But since only mean is needed, use reduce with addition, then divide by number of elements
  // Sum over dims 2 and 3
  %init_sum = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum_over_dims = "stablehlo.reduce"(%scaled, %init_sum) {
    dimensions = array<i64: 2, 3>
  } : (tensor<16x7x15x15xf32>, tensor<f32>) -> tensor<16x7xf32>
  // Compute number of elements summed: 15 * 15 = 225
  %divisor = "stablehlo.constant"() {value = dense<225.0> : tensor<f32>} : () -> tensor<f32>
  %avg1 = "stablehlo.divide"(%sum_over_dims, %divisor) : (tensor<16x7xf32>, tensor<f32>) -> tensor<16x7xf32>

  // Step 4: Second global average pooling over dims [2,3]
  // Expand dims to match shape for broadcasting
  // First, reshape %avg1 to shape [16,7,1,1]
  %avg1_reshaped = "stablehlo.reshape"(%avg1) {
    shape = tensor<16x7x1x1xf32>
  } : (tensor<16x7xf32>) -> tensor<16x7x1x1xf32>
  // Sum over dims 2 and 3 again
  %sum_over_dims2 = "stablehlo.reduce"(%avg1_reshaped, %init_sum) {
    dimensions = array<i64: 2, 3>
  } : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x7xf32>
  // Divide by 1 (since shape is 1x1, sum is the value itself)
  // But to keep consistent, divide by 1
  %divisor2 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %avg2 = "stablehlo.divide"(%sum_over_dims2, %divisor2) : (tensor<16x7xf32>, tensor<f32>) -> tensor<16x7xf32>
  // Reshape back to shape [16,7,1,1]
  %avg2_reshaped = "stablehlo.reshape"(%avg2) {
    shape = tensor<16x7x1x1xf32>
  } : (tensor<16x7xf32>) -> tensor<16x7x1x1xf32>

  // Step 5: Final output shape is [16,7,1,1], matching desired output
  // Return the final tensor
  return %avg2_reshaped : tensor<16x7x1x1xf32>
}

