        %min = "stablehlo.minimum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%min) : (tensor<f32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x1xf32>

    // Step 5: Squeeze dimension 1 (size 1) to get shape (16,16)
    // Reshape to (16,16)
    %x6 = "stablehlo.reshape"(%x5) : (tensor<16x1x16xf32>) -> tensor<16x16xf32>
    // Note: The shape after reduce is (16,16), so no need to reshape further

    // Step 6: Add bias again (from argument 2) to the result
    // Broadcast bias of shape (16,)
    %bias2_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    // Add bias
    %x7 = "stablehlo.add"(%x6, %bias2_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 7: Reshape to final shape (1,16,16,1)
    // First, reshape to (1,16,16,1)
    %x8 = "stablehlo.reshape"(%x7) : (tensor<16x16xf32>) -> tensor<1x16x16x1xf32>

    // Return the final tensor
    "stablehlo.return"(%x8) : (tensor<1x16x16x1xf32>) -> ()
  }
}

func.func @main(%arg0: tensor<16x8x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x8x16x16xf32>) -> tensor<16x1x14x14xf32> {
    // Step 1: Convolution
    %conv_weight = %arg0 : tensor<16x8x3x3xf32>
    %input = %arg4 : tensor<16x8x16x16xf32>
    %conv = "stablehlo.convolution"(%input, %conv_weight) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>
    // Note: The weight is passed as %arg0, but in the description, it's the first parameter, so adjust accordingly
    // For clarity, assign parameters:
    %conv_weight_param = %arg0 : tensor<16x8x3x3xf32>
    %input_tensor = %arg4 : tensor<16x8x16x16xf32>
    %conv_result = "stablehlo.convolution"(%input_tensor, %conv_weight_param) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>

    // Step 2: Group Normalization
    // Parameters: %arg1 (bias), %arg2 (weight)
    // Inputs: conv output
    // For simplicity, implement group norm as: normalized = (x - mean) / sqrt(var + eps) * weight + bias
    // But since batch stats are used, compute mean and variance over batch and spatial dims (dims 0,2,3)
    // Compute mean
    %axes = array<i64: 0, 2, 3>
    %mean = "stablehlo.reduce"(%conv_result, %c0 := "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) {
      dimensions = %axes
    } : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    // Compute variance
    // For variance, compute (x - mean)^2, then reduce mean
    %broadcast_mean = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = array<i64: 0, 2, 3>
    } : (tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    %diff = "stablehlo.subtract"(%conv_result, %broadcast_mean) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    %var = "stablehlo.reduce"(%diff_squared, %c0 : tensor<f32>) {
      dimensions = %axes
    } : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    // Compute variance mean
    %var_mean = "stablehlo.reduce"(%var, %c0 : tensor<f32>) {
      dimensions = array<i64: 0, 2, 3>
    } : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    // Add epsilon
    %eps = "stablehlo.constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %var_eps = "stablehlo.add"(%var_mean, %eps) : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    // Compute stddev
    %stddev = "stablehlo.math.sqrt"(%var_eps) : (tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    // Normalize
    %diff_norm = "stablehlo.divide"(%diff, %stddev) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    // Broadcast weight and bias
    %weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<16xf32>) -> tensor<16x16x14x14xf32>
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<16xf32>) -> tensor<16x16x14x14xf32>
    // Apply scale and shift
    %scaled = "stablehlo.multiply"(%diff_norm, %weight_bcast) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    %norm = "stablehlo.add"(%scaled, %bias_bcast) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 3: Tanh activation
    %tanh = "stablehlo.math.tanh"(%norm) : (tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 4: HardSwish
    // HardSwish: x * relu6(x + 3) / 6
    // Implement relu6 as min(max(x+3, 0), 6)
    %three = "stablehlo.constant"() {value = dense<3.0 : f32>} : () -> tensor<f32>
    %six = "stablehlo.constant"() {value = dense<6.0 : f32>} : () -> tensor<f32>
    %x_plus_3 = "stablehlo.add"(%tanh, %three) : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    %relu6_part = "stablehlo.maximum"(%x_plus_3, "stablehlo.constant"() {value = dense<0.0 : f32>}) : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    %relu6 = "stablehlo.minimum"(%relu6_part, %six) : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16x14x14xf32>
    // HardSwish: x * relu6(x+3) / 6
    %hard_swish_num = "stablehlo.multiply"(%tanh, %relu6) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    %hard_swish = "stablehlo.divide"(%hard_swish_num, %six) : (tensor<16x16x14x14xf32>, tensor<6.0>) -> tensor<16x16x14x14xf32>

