// StableHLO program to produce a lower triangular matrix with original values on and below the diagonal, zeros elsewhere.
func.func @main(%x: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %iota = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<6x6xi32>
  %iota_j = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6x6xi32>

  // Broadcast iota along the other dimension to get row indices for each element
  %rows = "stablehlo.broadcast_in_dim"(%iota, %iota_j) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<6x6xi32>) -> tensor<6x6xi32>

  // Compare column indices (iota) with row indices (broadcasted)
  %cmp = "stablehlo.compare"(%iota, %rows) {
    comparison_direction = #stablehlo<LT>,
    compare_type = #stablehlo<SIGNED>
  } : (tensor<6x6xi32>, tensor<6x6xi32>) -> tensor<6x6xi1>

  // Create a constant zero tensor for the upper triangle
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<6x6xf32>} : () -> tensor<6x6xf32>

  // Select original value where j <= i, else zero
  %result = "stablehlo.select"(%cmp, %x, %zero) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  return %result : tensor<6x6xf32>
}

// StableHLO program to produce a lower triangular matrix with the input tensor
// and zeros elsewhere, based on the condition j <= i.

func.func @main(%x: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // Generate row indices: iota along dimension 0
  %rows = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6x6xi32>
  // Generate column indices: iota along dimension 1
  %cols = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<6x6xi32>

  // Convert row indices to float for comparison
  %rows_f32 = "stablehlo.convert"(%rows) {to_element_type = "f32"} : (tensor<6x6xi32>) -> tensor<6x6xf32>
  // Convert column indices to float for comparison
  %cols_f32 = "stablehlo.convert"(%cols) {to_element_type = "f32"} : (tensor<6x6xi32>) -> tensor<6x6xf32>

  // Compare: j <= i (i.e., cols_f32 <= rows_f32)
  %cmp = "stablehlo.compare"(%cols_f32, %rows_f32) {
    comparison_direction = #stablehlo<LE>,
    compare_type = #stablehlo<SIGNED>
  } : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Select: if condition true, take from input x; else 0.0
  %zero = "stablehlo.constant"() {value = dense<0x00000000> : tensor<f32>} : () -> tensor<f32>
  %result = "stablehlo.select"(%cmp, %x, %zero) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  return %result : tensor<6x6xf32>
}

// StableHLO program implementing the described model forward pass
module {
  func.func @main(%arg0: tensor<1x16x1x1xf32>, 
                  %arg1: tensor<16x16xf32>, 
                  %arg2: tensor<16xf32>, 
                  %arg3: tensor<16xf32>, 
                  %arg4: tensor<16xf32>, 
                  %arg5: tensor<16x16xf32>) -> tensor<1x16x16x1xf32> {
    // Step 1: GEMM: x = matmul(%arg1, %arg0)
    %x = "stablehlo.dot_general"(%arg1, %arg0) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<16x16xf32>, tensor<1x16x1x1xf32>) -> tensor<16x16xf32>

    // Step 2: Reshape x to 2D for normalization: flatten batch and spatial dims
    // x shape: [16,16], reshape to [16,16]
    // Since shape is same, skip reshape, but for clarity, do reshape
    %x_reshaped = "stablehlo.reshape"(%x) : (tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 3: Batch normalization (using group norm in training mode)
    // group_norm: input shape: [16,16]
    // Parameters: weight and bias are vectors of size 16
    // For simplicity, simulate batch norm as: normalized_x = (x - mean) / sqrt(var + epsilon) * weight + bias
    // But since we only have parameters, and no mean/var, approximate as affine transform: x * weight + bias
    // For simplicity, perform element-wise multiply and add

    // Expand %arg3 (weight) to match shape
    // %arg3 shape: [16], need to broadcast to [16,16]
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>

    // Similarly for bias
    %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>

    // Element-wise multiply: normalized_x = x * weight_bcast
    %x_mul_weight = "stablehlo.multiply"(%x_reshaped, %gn_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Element-wise add bias
    %x_norm = "stablehlo.add"(%x_mul_weight, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 4: Reduce min over dimension 1 (columns)
    // Keepdim=True, so shape remains [16,1]
    %min_dim1 = "stablehlo.reduce"(%x_norm, %c_min, {dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x1xf32>
    // %c_min is constant -inf for float32
    %c_min = "stablehlo.constant"() {value = dense<0xFF800000> } : () -> tensor<f32>

    // Step 5: Add bias (%arg2) to min result
    // %arg2 shape: [16], broadcast to [16,1]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x1xf32>
    %min_plus_bias = "stablehlo.add"(%min_dim1, %bias_bcast) : (tensor<16x1xf32>, tensor<16x1xf32>) -> tensor<16x1xf32>

    // Step 6: Broadcast back to shape [16,16]
    %min_broadcast = "stablehlo.broadcast_in_dim"(%min_plus_bias) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16x1xf32>) -> tensor<16x16xf32>

    // Step 7: Add the bias parameter %arg5 (shape: [16x16]) to the result
    %bias_param_bcast = "stablehlo.broadcast_in_dim"(%arg5) {
      broadcast_dimensions = array<i64: 0, 1>
    } : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %add_bias_param = "stablehlo.add"(%min_broadcast, %bias_param_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 8: Reshape to output shape [1,16,16,1]
    %output = "stablehlo.reshape"(%add_bias_param) : (tensor<16x16xf32>) -> tensor<1x16x16x1xf32>

    // Return the output
    "stablehlo.return"(%output) : (tensor<1x16x16x1xf32>) -> ()
  }
}

func.func @main(%arg0: tensor<1x16x1x1xf32>, 
                 %arg1: tensor<16x16xf32>, 
                 %arg2: tensor<16xf32>, 
                 %arg3: tensor<16xf32>, 
                 %arg4: tensor<16xf32>, 
                 %arg5: tensor<16x16xf32>) -> tensor<1x16x16x1xf32> {
  // Step 1: GEMM: x = matmul(%arg5, %arg1)
  %x = "stablehlo.dot_general"(%arg5, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: Batch normalization (GroupNorm) with batch stats
  // For simplicity, assume mean and variance are computed as constants (simulate batch stats)
  // mean = 0.0, variance = 1.0 (placeholders)
  %mean = "stablehlo.constant"() {value = dense<0.0> } : () -> tensor<f32>
  %variance = "stablehlo.constant"() {value = dense<1.0> } : () -> tensor<f32>
  // epsilon for numerical stability
  %epsilon = "stablehlo.constant"() {value = dense<1.0e-5> } : () -> tensor<f32>

  // Broadcast mean and variance to shape of x
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x16xf32>
  %variance_bcast = "stablehlo.broadcast_in_dim"(%variance) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x16xf32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x16xf32>

  // Compute normalized: (x - mean) / sqrt(variance + epsilon)
  %x_minus_mean = "stablehlo.subtract"(%x, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %var_plus_epsilon = "stablehlo.add"(%variance_bcast, %epsilon_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %inv_sqrt_var = "stablehlo.rsqrt"(%var_plus_epsilon) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_norm = "stablehlo.multiply"(%x_minus_mean, %inv_sqrt_var) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 3: GroupNorm scale and bias
  // %arg3: weight, %arg4: bias
  // Broadcast scale and bias to shape of x_norm
  %scale_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Apply scale and bias: x_norm * scale + bias
  %scaled = "stablehlo.multiply"(%x_norm, %scale_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %gn_output = "stablehlo.add"(%scaled, %bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 4: Compute min over dimension 1 (dim=1), keepdim=True
  // For torch.min with dim=1, keepdim=True, output shape: (16,1)
  // For simplicity, simulate torch.min by reducing over dim=1 with minimum
  // We need to reduce over dimension 1
  // Prepare axes for reduction
  // Since reduction is over dim=1, axes = [1]
  // Use reduce operation
  %min_result = "stablehlo.reduce"(%gn_output, %c_zero) {
    ^bb0(%a: tensor<16x16xf32>, %b: tensor<16x16xf32>): 
      %s = "stablehlo.minimum"(%a, %b) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
  } {dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Now, to get the min over dim=1 with keepdim=True, we need to reshape
  // The reduce outputs shape: (16,1)
  // So, reshape min_result to shape (16,1)
  // But reduce returns shape (16,1), so no reshape needed

  // Step 5: Add bias (%arg2) to min result
  // %arg2 shape: (16)
  // Broadcast to shape (16,1)
  %bias_bcast2 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x1xf32>
  // But min_result shape: (16,1), so compatible
  // To match shapes, expand min_result to shape (16,1)
  // Already shape (16,1)
  // Add bias
  %min_plus_bias = "stablehlo.add"(%min_result, %bias_bcast2) : (tensor<16x1xf32>, tensor<16x1xf32>) -> tensor<16x1xf32>

  // Step 6: Add bias tensor (%arg2) to min_plus_bias
  // Already added bias in previous step, so skip
  // But in the original code, bias is added after min operation, so we have min_plus_bias as final

  // Step 7: Reshape min_plus_bias to match shape for addition with x
  // min_plus_bias shape: (16,1)
  // Broadcast to shape (1,16,16,1) for addition
  // First, expand dims to match
  // For simplicity, broadcast min_plus_bias to shape (1,16,16,1)
  // Create a tensor of shape (1,16,16,1) filled with min_plus_bias
  // But since min_plus_bias shape: (16,1), need to broadcast
  // Use broadcast_in_dim
  %min_broadcasted = "stablehlo.broadcast_in_dim"(%min_plus_bias) {
